use crate::{
	DispatchError,
	ExecutableNode,
	Input,
	InputSource,
	InspectableNode,
	InspectionError,
	NoInspectKind,
	NodeInspector,
	NodeMetadata,
	NoneInspect,
	RecoverableError,
};

/// A no-op terminal node.
///
/// This is mainly for testing purposes. It doesn't have any practical use, nor is it generated by the proc macro.
#[derive(Default)]
#[cfg_attr(feature = "const", derive(const_default::ConstDefault))]
pub struct Nil;

impl<Ctx, Stack, Source> ExecutableNode<Ctx, Stack, Source> for Nil
where
	Source: InputSource,
{
	fn execute(&self, _ctx: &mut Ctx, input: &mut Input<Source>, stack: Stack) -> Result<(), DispatchError<Stack>> {
		if input.has_remaining() {
			Err(DispatchError::Recoverable(RecoverableError::UnknownCommand { offset: input.offset }, stack))
		} else {
			Err(DispatchError::Recoverable(RecoverableError::IncompleteCommand, stack))
		}
	}
}

impl NodeMetadata for Nil {
	type Inspect = NoneInspect;
	type Kind = NoInspectKind;
}

impl<Source: InputSource> InspectableNode<Source> for Nil {
	fn inspect(&self, _inspector: &mut NodeInspector, input: &mut Input<Source>) -> Result<(), InspectionError> {
		if input.has_remaining() {
			Err(InspectionError::UnknownCommand { offset: input.offset })
		} else {
			Err(InspectionError::IncompleteCommand)
		}
	}
}
